import os
import re

d = os.environ.get('RLM_SESSION_DIR', '')
sessions_file = os.path.join(d, 'semantic-edges.jsonl')

with open(sessions_file, 'r') as f:
    content = f.read()

# Parse for demo pairs
demos = []
lines = content.split('\n')
current_kind = None
current_dims = None
current_rows = []

for line in lines:
    if 'Demo pair' in line or 'Test input' in line:
        if current_kind is not None and current_rows:
            demos.append((current_kind, current_dims, current_rows))

        if 'input' in line:
            match = re.search(r'(\d+)x(\d+)', line)
            current_kind, current_dims = ('input', (int(match.group(1)), int(match.group(2))))
            current_rows = []
        elif 'output' in line:
            match = re.search(r'(\d+)x(\d+)', line)
            current_kind, current_dims = ('output', (int(match.group(1)), int(match.group(2))))
            current_rows = []
    else:
        # Try to parse as grid row
        if line.strip():
            parts = line.strip().split()
            if len(parts) == current_dims[1] if current_kind else len(parts) <= 9:
                current_rows.append([int(x) for x in parts])

if current_kind is not None and current_rows:
    demos.append((current_kind, current_dims, current_rows))

print(f"Found {len(demos)} pairs")
for i, (kind, dims, rows) in enumerate(demos):
    print(f"\n[{kind}] {dims}:")
    for r in rows[:5]:
        print('  ' + ' '.join(str(x) for x in r))
    if len(rows) > 5:
        print(f"  ... ({len(rows)} rows total)")

import os
import json

d = os.environ.get('RLM_SESSION_DIR', '')
sessions_file = os.path.join(d, 'semantic-edges.jsonl')

all_keys = set()
with open(sessions_file, 'r') as f:
    for line in f:
        if not line.strip():
            continue
        try:
            msg = json.loads(line)
            all_keys.update(msg.keys())
            # Also collect nested keys
            for v in msg.values():
                if isinstance(v, dict):
                    all_keys.update(v.keys())
        except:
            pass

print(json.dumps(sorted(all_keys), indent=2))

